-- PRIVATE working delivery. Membership acceptance is separate from instrument/family/PIT qualification.
CREATE TABLE population_top3000_202608_202609_v1.practical_delivery_release_v1(release_id text PRIMARY KEY,publication_id uuid NOT NULL,delivery_id uuid NOT NULL,manifest jsonb NOT NULL,manifest_sha256 text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE population_top3000_202608_202609_v1.practical_delivery_coverage_v1(release_id text NOT NULL REFERENCES population_top3000_202608_202609_v1.practical_delivery_release_v1,family_id text NOT NULL,unit_key text NOT NULL,content jsonb NOT NULL,record_sha256 text NOT NULL,PRIMARY KEY(release_id,family_id,unit_key));
CREATE TABLE population_top3000_202608_202609_v1.practical_delivery_batch_v1(release_id text NOT NULL REFERENCES population_top3000_202608_202609_v1.practical_delivery_release_v1,dataset text NOT NULL,partition_key text NOT NULL,row_count bigint NOT NULL,rows_sha256 text NOT NULL,source_projection text NOT NULL,PRIMARY KEY(release_id,dataset,partition_key));
CREATE TABLE population_top3000_202608_202609_v1.practical_delivery_snapshot_row_v1(release_id text NOT NULL,dataset text NOT NULL,ordinal integer NOT NULL,content jsonb NOT NULL,record_sha256 text NOT NULL,PRIMARY KEY(release_id,dataset,ordinal));
ALTER TABLE population_top3000_202608_202609_v1.practical_delivery_snapshot_row_v1 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON population_top3000_202608_202609_v1.practical_delivery_snapshot_row_v1 FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE population_top3000_202608_202609_v1.practical_delivery_saved_export_v1(release_id text NOT NULL REFERENCES population_top3000_202608_202609_v1.practical_delivery_release_v1,dataset text NOT NULL,receipt jsonb NOT NULL,receipt_sha256 text NOT NULL,PRIMARY KEY(release_id,dataset));
ALTER TABLE population_top3000_202608_202609_v1.practical_delivery_release_v1 ENABLE ROW LEVEL SECURITY;
ALTER TABLE population_top3000_202608_202609_v1.practical_delivery_coverage_v1 ENABLE ROW LEVEL SECURITY;
ALTER TABLE population_top3000_202608_202609_v1.practical_delivery_batch_v1 ENABLE ROW LEVEL SECURITY;
ALTER TABLE population_top3000_202608_202609_v1.practical_delivery_saved_export_v1 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON population_top3000_202608_202609_v1.practical_delivery_release_v1,population_top3000_202608_202609_v1.practical_delivery_coverage_v1,population_top3000_202608_202609_v1.practical_delivery_batch_v1,population_top3000_202608_202609_v1.practical_delivery_saved_export_v1 FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION population_top3000_202608_202609_v1.practical_delivery_guard_v1(p_release text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $f$
DECLARE a population_top3000_202608_202609_v1.acquisition_control%rowtype;p population_top3000_202608_202609_v1.pipeline_control%rowtype;r population_top3000_202608_202609_v1.practical_delivery_release_v1%rowtype;n bigint;it record;
BEGIN
SELECT * INTO STRICT a FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton;SELECT * INTO STRICT p FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton;
IF a.owner_id IS DISTINCT FROM 'top3000-completion-20261024-root-5db48b32d103' OR a.owner_fence IS DISTINCT FROM 3 OR a.stop_generation IS DISTINCT FROM 1 OR a.enabled IS DISTINCT FROM true OR a.stopped IS DISTINCT FROM false OR a.hold_reason IS NOT NULL OR p.enabled IS DISTINCT FROM true OR p.expected_owner_id IS DISTINCT FROM a.owner_id OR p.expected_owner_fence IS DISTINCT FROM 3 OR p.expected_stop_generation IS DISTINCT FROM 1 OR a.scope_sha256 IS DISTINCT FROM '8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd' OR p.scope_sha256 IS DISTINCT FROM a.scope_sha256 OR a.admitted_until IS NULL OR p.deadline IS NULL OR a.admitted_until<=clock_timestamp() OR p.deadline<=clock_timestamp() THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_OWNER_STOP_SCOPE_ADMISSION';END IF;
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ref01_practical_membership_v1 WHERE snapshot_sha256='2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec' AND acceptance_sha256='20b9dac759857e9b510ccaeca33e4a94d8c748d588fb0cc27740cc66c389b5f9' AND acceptance_sha256=encode(sha256(convert_to(content::text,'UTF8')),'hex') AND content->>'membership_accepted'='true' AND content->>'company_count'='3000' AND content->>'family_acceptance'='false') THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_MEMBERSHIP_PIN';END IF;
SELECT count(*) INTO n FROM population_top3000_202608_202609_v1.working_accepted_companies_v1;IF n<>3000 THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_COMPANY_COUNT';END IF;
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.daily_shared_run_v1 WHERE run_id='19a35bfa-6023-4092-9809-3ed950871d7f' AND series_count=13044 AND normalized_series=series_count AND derived_series=series_count AND encode(sha256(convert_to(input_versions::text,'UTF8')),'hex')='6fe3d08080861b40b3d4c7cd0763a18a4fdf861d533b4a63c3164a8c1a23c539') THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_DAILY_INPUT_PIN';END IF;
IF p_release IS NOT NULL THEN
SELECT * INTO STRICT r FROM population_top3000_202608_202609_v1.practical_delivery_release_v1 WHERE release_id=p_release;
IF r.manifest_sha256 IS DISTINCT FROM encode(sha256(convert_to(r.manifest::text,'UTF8')),'hex') OR r.manifest->>'cohort_sha256' IS DISTINCT FROM '2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec' OR r.manifest->>'membership_acceptance_sha256' IS DISTINCT FROM '20b9dac759857e9b510ccaeca33e4a94d8c748d588fb0cc27740cc66c389b5f9' OR r.manifest->>'final_delivery' IS DISTINCT FROM 'false' OR r.manifest->>'runtime_not_after' IS NULL OR (r.manifest->>'runtime_not_after')::timestamptz<=clock_timestamp() THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_RELEASE_PIN';END IF;
IF jsonb_typeof(r.manifest->'function_hashes') IS DISTINCT FROM 'object' OR jsonb_typeof(r.manifest->'view_hashes') IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(r.manifest->'function_hashes'))<>8 OR (SELECT count(*) FROM jsonb_object_keys(r.manifest->'view_hashes'))<>4 OR NOT ((r.manifest->'view_hashes')?&ARRAY['population_top3000_202608_202609_v1.working_accepted_companies_v1','population_top3000_202608_202609_v1.working_daily_features_v1','population_top3000_202608_202609_v1.working_breadth_preliminary_v1','population_top3000_202608_202609_v1.working_family_readiness_v1']) OR EXISTS(SELECT 1 FROM pg_proc q WHERE q.pronamespace='population_top3000_202608_202609_v1'::regnamespace AND q.proname LIKE 'practical_delivery_%_v1' AND NOT(r.manifest->'function_hashes' ? q.oid::regprocedure::text)) THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_REQUIRED_MANIFEST_MAPS';END IF;
FOR it IN SELECT * FROM jsonb_each_text(r.manifest->'function_hashes') LOOP IF it.value IS DISTINCT FROM encode(sha256(convert_to(pg_get_functiondef(it.key::regprocedure),'UTF8')),'hex') THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_CODE_CHANGED';END IF;END LOOP;
FOR it IN SELECT * FROM jsonb_each_text(r.manifest->'view_hashes') LOOP IF it.value IS DISTINCT FROM encode(sha256(convert_to(pg_get_viewdef(it.key::regclass,true),'UTF8')),'hex') THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_VIEW_CHANGED';END IF;END LOOP;
END IF;
RETURN jsonb_build_object('company_membership_accepted',true,'accepted_company_count',3000,'full_period_instrument_coverage_accepted',false,'family_acceptance',false,'source_accuracy_qualified',false,'strict_point_in_time_qualified',false,'final_delivery',false);
END;$f$;

CREATE FUNCTION population_top3000_202608_202609_v1.practical_delivery_gate_v1() RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $f$
DECLARE g jsonb;c bigint;BEGIN g:=population_top3000_202608_202609_v1.practical_delivery_guard_v1();
SELECT count(*) INTO c FROM population_top3000_202608_202609_v1.pipeline_partition p JOIN population_top3000_202608_202609_v1.pipeline_validation v ON v.validation_id=p.last_validation_id JOIN population_top3000_202608_202609_v1.pipeline_family_binding b ON b.family_id=p.family_id WHERE p.denominator_state='FROZEN' AND p.publication_eligible AND v.result='PASS' AND cardinality(b.required_check_codes)>0 AND v.input_versions->>'membership_acceptance_sha256'='20b9dac759857e9b510ccaeca33e4a94d8c748d588fb0cc27740cc66c389b5f9' AND NOT EXISTS(SELECT 1 FROM unnest(b.required_check_codes) k WHERE NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_quality_evidence e WHERE e.family_id=p.family_id AND e.partition_key=p.partition_key AND e.check_code=k AND e.result='PASS' AND e.independent_of_producer AND e.input_versions=v.input_versions));
RETURN g||jsonb_build_object('legacy_generic_final_gate',population_top3000_202608_202609_v1.pipeline_full_gate_v1(),'independently_checked_partition_candidates',c,'candidate_is_root_acceptance',false,'qualified_release_admitted',false,'company_and_instrument_denominators_distinct',true,'working_private_delivery_allowed',true);END;$f$;

CREATE FUNCTION population_top3000_202608_202609_v1.practical_delivery_rows_v1(p_dataset text,p_partition text DEFAULT '*') RETURNS SETOF jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $f$
BEGIN
IF p_dataset='companies' THEN RETURN QUERY SELECT to_jsonb(c) FROM population_top3000_202608_202609_v1.working_accepted_companies_v1 c ORDER BY c.selection_order;
ELSIF p_dataset='daily_features' THEN RETURN QUERY SELECT to_jsonb(w) FROM population_top3000_202608_202609_v1.working_daily_features_v1 w WHERE w.session_date=CASE WHEN p_partition='*' THEN w.session_date ELSE p_partition::date END ORDER BY w.session_date,w.company_id;
ELSIF p_dataset='daily_close_volume' THEN RETURN QUERY SELECT jsonb_build_object('company_id',w.company_id,'source_ticker',w.source_ticker,'session_date',w.session_date,'raw_close',i.raw_close,'raw_volume',i.raw_volume,'dollar_volume',i.dollar_volume,'source_count',i.source_count,'source_kind',i.source_kind,'source_key',i.source_key,'price_basis',i.price_basis,'unknown_actions',i.unknown_actions,'input_quality_mask',i.quality_mask,'source_record_sha256',encode(i.source_record_sha256,'hex'),'input_record_sha256',encode(i.input_record_sha256,'hex'),'cohort_sha256',w.cohort_sha256,'membership_acceptance_sha256',w.membership_acceptance_sha256,'qualification_state','PRELIMINARY_ANCHOR_SESSION_RETAINED_SOURCE','full_period_instrument_denominator_known',false,'source_accuracy_qualified',false,'strict_point_in_time_qualified',false,'family_accepted',false,'missing_is_zero',false) FROM population_top3000_202608_202609_v1.working_daily_features_v1 w LEFT JOIN population_top3000_202608_202609_v1.daily_shared_input_v1 i ON i.run_id=w.run_id AND i.series_no=w.series_no AND i.session_date=w.session_date WHERE w.session_date=CASE WHEN p_partition='*' THEN w.session_date ELSE p_partition::date END ORDER BY w.session_date,w.company_id;
ELSIF p_dataset='breadth' THEN RETURN QUERY SELECT to_jsonb(b) FROM population_top3000_202608_202609_v1.working_breadth_preliminary_v1 b ORDER BY b.session_date;
ELSIF p_dataset='readiness' THEN IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.practical_delivery_snapshot_row_v1 WHERE release_id='practical-delivery-v1-74907' AND dataset='readiness') THEN RETURN QUERY SELECT r.content FROM population_top3000_202608_202609_v1.practical_delivery_snapshot_row_v1 r WHERE release_id='practical-delivery-v1-74907' AND dataset='readiness' ORDER BY ordinal;ELSE RETURN QUERY SELECT to_jsonb(r) FROM population_top3000_202608_202609_v1.working_family_readiness_v1 r ORDER BY r.family_id;END IF;
ELSIF p_dataset='S02_archive' THEN IF p_partition!~'^[0-9]+$' OR p_partition::int NOT BETWEEN 1 AND 135 THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_S02_PAGE';END IF; RETURN QUERY SELECT x.value FROM jsonb_array_elements(population_top3000_202608_202609_v1.population_archive_read_batch_v1('1516e35a-b313-49fc-8b85-cf9128673be3','S02',p_partition::int,1)->'rows') x;
ELSE RAISE EXCEPTION 'PRACTICAL_DELIVERY_DATASET';END IF;END;$f$;

CREATE FUNCTION population_top3000_202608_202609_v1.practical_delivery_digest_v1(p_dataset text,p_partition text DEFAULT '*') RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $f$
SELECT jsonb_build_object('row_count',count(*),'rows_sha256',encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(row::text,'UTF8')),'hex'),chr(10) ORDER BY ord),''),'UTF8')),'hex'),'digest_method','SHA256_OF_ORDERED_NEWLINE_CANONICAL_JSONB_ROW_SHA256') FROM(SELECT z.row,row_number()over()ord FROM population_top3000_202608_202609_v1.practical_delivery_rows_v1(p_dataset,p_partition)z(row))x;
$f$;

CREATE FUNCTION population_top3000_202608_202609_v1.practical_delivery_read_v1(p_release text,p_dataset text,p_partition text DEFAULT '*',p_offset integer DEFAULT 0,p_limit integer DEFAULT 3000,p_qualified_only boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $f$
DECLARE rows jsonb;n bigint;cols jsonb;BEGIN PERFORM population_top3000_202608_202609_v1.practical_delivery_guard_v1(p_release);
IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 5000 OR p_offset IS NULL OR p_offset<0 THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_PAGE_BOUND';END IF;
IF p_qualified_only IS DISTINCT FROM false THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_QUALIFIED_RELEASE_NOT_ADMITTED';END IF;
SELECT coalesce(jsonb_agg(x.row ORDER BY x.ord),'[]'),count(*) INTO rows,n FROM(SELECT z.row,row_number()over()ord FROM population_top3000_202608_202609_v1.practical_delivery_rows_v1(p_dataset,p_partition) z(row) OFFSET p_offset LIMIT p_limit)x;
SELECT coalesce(jsonb_agg(k ORDER BY k),'[]') INTO cols FROM jsonb_object_keys(coalesce(rows->0,'{}'))k;
RETURN jsonb_build_object('release_id',p_release,'dataset',p_dataset,'partition',p_partition,'offset',p_offset,'limit',p_limit,'row_count',n,'next_offset',CASE WHEN n=p_limit THEN p_offset+n END,'rows',rows,'rows_sha256',encode(sha256(convert_to(rows::text,'UTF8')),'hex'),'export_column_manifest',cols,'export_column_manifest_sha256',encode(sha256(convert_to(cols::text,'UTF8')),'hex'),'source_projection',CASE p_dataset WHEN 'companies' THEN 'working_accepted_companies_v1' WHEN 'daily_features' THEN 'working_daily_features_v1' WHEN 'breadth' THEN 'working_breadth_preliminary_v1' WHEN 'readiness' THEN 'working_family_readiness_v1' WHEN 'daily_close_volume' THEN 'DAILY_SHARED_INPUT_RAW_ANCHOR_SESSION' ELSE 'S02_SOURCE_ARCHIVE_PAGE' END,'qualification','PRIVATE_PRELIMINARY_WORKING_NOT_FAMILY_ACCEPTANCE','strict_point_in_time_qualified',false,'source_accuracy_qualified',false,'full_period_instrument_coverage_accepted',false,'final_delivery',false);END;$f$;

CREATE FUNCTION population_top3000_202608_202609_v1.practical_delivery_bootstrap_v1(p_review bigint) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $f$
DECLARE r text:='practical-delivery-v1-74907';m jsonb;h text;pub uuid:=gen_random_uuid();del uuid:=gen_random_uuid();vh jsonb;fh jsonb;g jsonb;t1 uuid;t2 uuid;iv jsonb;until_at timestamptz;dm jsonb:='{}';ds text;rev jsonb;
BEGIN
PERFORM population_top3000_202608_202609_v1.practical_delivery_guard_v1();
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=75105 AND event='ENGINEERING_ASSIGNMENT_CLAIMED_V5' AND details->>'assignment_event_id'='74907' AND details->>'assignment_details_sha256'='2390d79406c9269cd7f76a6ec4f5ea5675c1d53616a129e18fe82867e6bac064' AND (details->>'expires_at')::timestamptz>clock_timestamp()) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event IN('ENGINEERING_ASSIGNMENT_COMPLETED_V5','ENGINEERING_ASSIGNMENT_EFFECTS_RECONCILED_RELEASE_V5') AND details->>'claim_event_id'='75105') THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_EXACT_ACTIVE_CLAIM';END IF;
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=p_review AND event='ENGINEERING_INDEPENDENT_CODE_REVIEW_V5' AND details->>'approved'='true' AND details->>'actual_rollback_passed'='true' AND details->>'assignment_event_id'='74907' AND details->>'claim_event_id'='75105' AND nullif(details->>'producer','') IS NOT NULL AND nullif(details->>'reviewer','') IS NOT NULL AND details->>'reviewer' IS DISTINCT FROM details->>'producer' AND (details->>'fixture_only'='false' OR (details->>'fixture_only'='true' AND current_setting('practical_delivery.rollback_fixture',true)='on'))) THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_DISTINCT_REVIEW';END IF;
IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.practical_delivery_release_v1 WHERE release_id=r) THEN PERFORM population_top3000_202608_202609_v1.practical_delivery_guard_v1(r);RETURN jsonb_build_object('release_id',r,'state','ALREADY_PREPARED');END IF;
SELECT jsonb_object_agg(oid::regprocedure::text,encode(sha256(convert_to(pg_get_functiondef(oid),'UTF8')),'hex')) INTO fh FROM pg_proc WHERE pronamespace='population_top3000_202608_202609_v1'::regnamespace AND proname LIKE 'practical_delivery_%_v1';
SELECT jsonb_object_agg('population_top3000_202608_202609_v1.'||viewname,encode(sha256(convert_to(pg_get_viewdef(('population_top3000_202608_202609_v1.'||viewname)::regclass,true),'UTF8')),'hex')) INTO vh FROM pg_views WHERE schemaname='population_top3000_202608_202609_v1' AND viewname IN('working_accepted_companies_v1','working_daily_features_v1','working_breadth_preliminary_v1','working_family_readiness_v1');
SELECT least(admitted_until,(SELECT deadline FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton)) INTO until_at FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton;
SELECT details INTO STRICT rev FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=p_review;IF rev->'sql_function_hashes' IS DISTINCT FROM fh THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_REVIEW_CODE_BINDING';END IF;
FOREACH ds IN ARRAY ARRAY['companies','daily_features','breadth','readiness'] LOOP dm:=dm||jsonb_build_object(ds,population_top3000_202608_202609_v1.practical_delivery_digest_v1(ds,'*'));END LOOP;
g:=population_top3000_202608_202609_v1.practical_delivery_gate_v1();m:=g||jsonb_build_object('cohort_sha256','2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec','membership_acceptance_sha256','20b9dac759857e9b510ccaeca33e4a94d8c748d588fb0cc27740cc66c389b5f9','policy_sha256','3e49d661fcdb8533e5ce88a85689b41e9dde71eeae2dc8578c9e31f9ae1738bb','daily_run_id','19a35bfa-6023-4092-9809-3ed950871d7f','daily_independent_review_event_id',31414,'implementation_review_event_id',p_review,'function_hashes',fh,'view_hashes',vh,'dataset_value_manifests',dm,'readiness_snapshot_asof',clock_timestamp(),'runtime_not_after',until_at,'working_views_installation_event_id',74817,'classification','PRIVATE_PRELIMINARY_WORKING','expected_export_rows',jsonb_build_object('companies',3000,'daily_features',126000,'breadth',42,'readiness',24),'full_instrument_observation_denominator',NULL,'source_accuracy_qualified',false,'strict_point_in_time_qualified',false,'final_delivery',false,'exports_are_actual_client_files_only',true);
h:=encode(sha256(convert_to(m::text,'UTF8')),'hex');
INSERT INTO population_top3000_202608_202609_v1.pipeline_publication VALUES(pub,'PROVISIONAL_SOURCE_EVIDENCE','4134b415e2c26fcde9fced749c0d54ef51376e23f0d2f8c6ce9ef562f9fab99f',NULL,m,h,clock_timestamp(),NULL);
INSERT INTO population_top3000_202608_202609_v1.pipeline_delivery(delivery_id,publication_id,manifest,manifest_sha256) VALUES(del,pub,m||jsonb_build_object('consumer_function','population_top3000_202608_202609_v1.practical_delivery_read_v1','release_id',r),encode(sha256(convert_to((m||jsonb_build_object('consumer_function','population_top3000_202608_202609_v1.practical_delivery_read_v1','release_id',r))::text,'UTF8')),'hex'));
INSERT INTO population_top3000_202608_202609_v1.practical_delivery_release_v1 VALUES(r,pub,del,m,h,clock_timestamp());
INSERT INTO population_top3000_202608_202609_v1.practical_delivery_snapshot_row_v1 SELECT r,'readiness',row_number()OVER(ORDER BY x.family_id),to_jsonb(x),encode(sha256(convert_to(to_jsonb(x)::text,'UTF8')),'hex') FROM population_top3000_202608_202609_v1.working_family_readiness_v1 x;
iv:=jsonb_build_object('scope_sha256','8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd','cohort_sha256',m->>'cohort_sha256','membership_acceptance_sha256',m->>'membership_acceptance_sha256','release_id',r,'release_manifest_sha256',h);
t1:=population_top3000_202608_202609_v1.pipeline_enqueue_v1('REF03','DELIVER','practical-delivery:'||r||':verify:D02',jsonb_build_object('kind','PRACTICAL_DELIVERY_VERIFY_V1','target_family','D02','release_id',r),iv);
t2:=population_top3000_202608_202609_v1.pipeline_enqueue_v1('REF03','DELIVER','practical-delivery:'||r||':verify:S02',jsonb_build_object('kind','PRACTICAL_DELIVERY_VERIFY_V1','target_family','S02','release_id',r),iv);
RETURN jsonb_build_object('release_id',r,'publication_id',pub,'delivery_id',del,'manifest_sha256',h,'D02_verification_task_id',t1,'S02_verification_task_id',t2,'maximum_created_tasks',47,'final_release_pointer_changed',false,'family_accepted',false);
END;$f$;

CREATE FUNCTION population_top3000_202608_202609_v1.practical_delivery_worker_v1(p_attempt uuid,p_token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $f$
DECLARE tid uuid;t population_top3000_202608_202609_v1.pipeline_task%rowtype;r population_top3000_202608_202609_v1.practical_delivery_release_v1%rowtype;cnt bigint:=0;h text;one record;v jsonb;ds text;pk text;succ uuid;succs jsonb:='[]';iv jsonb;n bigint;
BEGIN tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);SELECT * INTO STRICT t FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=tid;
IF t.family_id IS DISTINCT FROM 'REF03' OR t.stage IS DISTINCT FROM 'DELIVER' OR t.payload->>'kind' IS NULL OR t.payload->>'kind' NOT IN('PRACTICAL_DELIVERY_VERIFY_V1','PRACTICAL_DELIVERY_EXPORT_V1') THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_TASK_SCOPE';END IF;
PERFORM population_top3000_202608_202609_v1.practical_delivery_guard_v1(t.payload->>'release_id');SELECT * INTO STRICT r FROM population_top3000_202608_202609_v1.practical_delivery_release_v1 WHERE release_id=t.payload->>'release_id';
IF t.input_versions->>'release_id' IS DISTINCT FROM r.release_id OR t.input_versions->>'release_manifest_sha256' IS DISTINCT FROM r.manifest_sha256 OR t.input_versions->>'cohort_sha256' IS DISTINCT FROM r.manifest->>'cohort_sha256' OR t.input_versions->>'membership_acceptance_sha256' IS DISTINCT FROM r.manifest->>'membership_acceptance_sha256' THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_TASK_INPUT_PIN';END IF;
IF t.payload->>'kind'='PRACTICAL_DELIVERY_VERIFY_V1' THEN
IF t.payload->>'target_family'='D02' THEN
FOR one IN WITH w AS MATERIALIZED(SELECT * FROM population_top3000_202608_202609_v1.working_daily_features_v1) SELECT w.session_date,count(*)expected_anchor_units,count(*)FILTER(WHERE i.source_count=1)source_single_rows,count(*)FILTER(WHERE i.source_count=0)source_missing_rows,count(*)FILTER(WHERE i.source_count>1)source_conflicting_rows,count(*)FILTER(WHERE i.source_count IS NULL)source_unknown_rows,count(*)FILTER(WHERE i.source_count=1 AND i.raw_close IS NOT NULL AND i.raw_volume IS NOT NULL AND i.dollar_volume IS NOT NULL)raw_fields_present_rows,count(*)FILTER(WHERE w.calculated_row_present)derived_rows,count(*)FILTER(WHERE i.unknown_actions>0)action_unknown_rows FROM w LEFT JOIN population_top3000_202608_202609_v1.daily_shared_input_v1 i ON i.run_id=w.run_id AND i.series_no=w.series_no AND i.session_date=w.session_date GROUP BY w.session_date ORDER BY w.session_date LOOP
v:=to_jsonb(one)||jsonb_build_object('unit','ANCHOR_COMPANY_SESSION_NOT_FULL_INSTRUMENT_DENOMINATOR','full_instrument_expected_units',NULL,'qualified_rows',0,'qualification','RETAINED_PRELIMINARY_SOURCE_VALUES_NOT_INDEPENDENT_ACCURACY','missing_is_zero',false,'family_accepted',false);
INSERT INTO population_top3000_202608_202609_v1.practical_delivery_coverage_v1 VALUES(r.release_id,'D02',one.session_date::text,v,encode(sha256(convert_to(v::text,'UTF8')),'hex')) ON CONFLICT DO NOTHING;GET DIAGNOSTICS n=ROW_COUNT;cnt:=cnt+n;IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.practical_delivery_coverage_v1 c WHERE c.release_id=r.release_id AND c.family_id='D02' AND c.unit_key=one.session_date::text AND c.content=v AND c.record_sha256=encode(sha256(convert_to(v::text,'UTF8')),'hex')) THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_COVERAGE_REPLAY_CONFLICT';END IF;
END LOOP;
IF (SELECT count(*) FROM population_top3000_202608_202609_v1.practical_delivery_coverage_v1 WHERE release_id=r.release_id AND family_id='D02')<>42 OR (SELECT sum((content->>'expected_anchor_units')::bigint) FROM population_top3000_202608_202609_v1.practical_delivery_coverage_v1 WHERE release_id=r.release_id AND family_id='D02')<>126000 THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_D02_GRID_DEVIATION';END IF;
FOR one IN SELECT unit_key FROM population_top3000_202608_202609_v1.practical_delivery_coverage_v1 WHERE release_id=r.release_id AND family_id='D02' ORDER BY unit_key LOOP succ:=population_top3000_202608_202609_v1.pipeline_enqueue_v1('REF03','DELIVER','practical-delivery:'||r.release_id||':export:daily_features:'||one.unit_key,jsonb_build_object('kind','PRACTICAL_DELIVERY_EXPORT_V1','release_id',r.release_id,'dataset','daily_features','partition',one.unit_key),t.input_versions,tid);succs:=succs||jsonb_build_array(succ);END LOOP;
FOREACH ds IN ARRAY ARRAY['companies','breadth','readiness'] LOOP succ:=population_top3000_202608_202609_v1.pipeline_enqueue_v1('REF03','DELIVER','practical-delivery:'||r.release_id||':export:'||ds,jsonb_build_object('kind','PRACTICAL_DELIVERY_EXPORT_V1','release_id',r.release_id,'dataset',ds,'partition','*'),t.input_versions,tid);succs:=succs||jsonb_build_array(succ);END LOOP;
ELSIF t.payload->>'target_family'='S02' THEN
IF (SELECT count(*) FROM population_top3000_202608_202609_v1.archive_publication_member_v1 WHERE publication_id='1516e35a-b313-49fc-8b85-cf9128673be3' AND family_id='S02')<>135 OR (SELECT sum(b.row_count) FROM population_top3000_202608_202609_v1.archive_publication_member_v1 m JOIN population_top3000_202608_202609_v1.archive_delivery_batch_v1 b USING(publication_id,snapshot_id) WHERE m.publication_id='1516e35a-b313-49fc-8b85-cf9128673be3' AND m.family_id='S02')<>134931 THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_S02_SOURCE_PAGE_PIN';END IF;
FOR one IN SELECT * FROM(VALUES('2026-07-15',22373,false),('2026-07-31',22339,false),('2026-08-14',22480,true),('2026-08-31',22567,true),('2026-09-15',22593,true),('2026-09-30',22579,true))x(settlement_date,source_rows,target_window) LOOP
v:=to_jsonb(one)||jsonb_build_object('unit','SOURCE_ARCHIVE_SECURITY_SETTLEMENT_ROWS_NOT_COHORT_DENOMINATOR','archive_publication_id','1516e35a-b313-49fc-8b85-cf9128673be3','source_page_count',135,'retained_source_mechanics_review',6277,'retained_evidence_file_sha256','8cebb460c9c1aa64384812d4dbbdbfffbbd2807c920139a2015df77d252e5292','full_instrument_expected_units',NULL,'qualified_rows',0,'qualification','SOURCE_ARCHIVE_ONLY','original_wire_rehash_verified',false,'independent_source_accuracy_verified',false,'strict_point_in_time_qualified',false,'family_accepted',false,'missing_is_zero',false);
INSERT INTO population_top3000_202608_202609_v1.practical_delivery_coverage_v1 VALUES(r.release_id,'S02',one.settlement_date,v,encode(sha256(convert_to(v::text,'UTF8')),'hex')) ON CONFLICT DO NOTHING;GET DIAGNOSTICS n=ROW_COUNT;cnt:=cnt+n;IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.practical_delivery_coverage_v1 c WHERE c.release_id=r.release_id AND c.family_id='S02' AND c.unit_key=one.settlement_date AND c.content=v AND c.record_sha256=encode(sha256(convert_to(v::text,'UTF8')),'hex')) THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_COVERAGE_REPLAY_CONFLICT';END IF;END LOOP;
ELSE RAISE EXCEPTION 'PRACTICAL_DELIVERY_TARGET_FAMILY';END IF;
SELECT encode(sha256(convert_to(jsonb_agg(jsonb_build_object('unit_key',unit_key,'hash',record_sha256) ORDER BY unit_key)::text,'UTF8')),'hex') INTO h FROM population_top3000_202608_202609_v1.practical_delivery_coverage_v1 WHERE release_id=r.release_id AND family_id=t.payload->>'target_family';
ELSE
ds:=t.payload->>'dataset';pk:=t.payload->>'partition';v:=population_top3000_202608_202609_v1.practical_delivery_read_v1(r.release_id,ds,pk,0,5000,false);n:=(v->>'row_count')::bigint;
IF n IS DISTINCT FROM (CASE ds WHEN 'daily_features' THEN 3000 WHEN 'companies' THEN 3000 WHEN 'breadth' THEN 42 WHEN 'readiness' THEN 24 ELSE -1 END) THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_EXPORT_COUNT';END IF;
h:=v->>'rows_sha256';INSERT INTO population_top3000_202608_202609_v1.practical_delivery_batch_v1 VALUES(r.release_id,ds,pk,n,h,v->>'source_projection') ON CONFLICT DO NOTHING;GET DIAGNOSTICS cnt=ROW_COUNT;
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.practical_delivery_batch_v1 WHERE release_id=r.release_id AND dataset=ds AND partition_key=pk AND rows_sha256=h AND row_count=n) THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_EXPORT_REPLAY_CONFLICT';END IF;
END IF;
IF (SELECT count(*) FROM population_top3000_202608_202609_v1.pipeline_task WHERE payload->>'release_id'=r.release_id AND payload->>'kind' IN('PRACTICAL_DELIVERY_VERIFY_V1','PRACTICAL_DELIVERY_EXPORT_V1'))>47 THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_TASK_LIMIT';END IF;
RETURN jsonb_build_object('state','COMPLETE','commit_receipt',jsonb_build_object('commit_key','practical-delivery:'||tid::text,'output_sha256',h,'new_committed_units',cnt,'immutable_output_ids',jsonb_build_array(r.release_id||':'||coalesce(ds,t.payload->>'target_family')||':'||coalesce(pk,'coverage')),'input_versions',t.input_versions,'qualification','PRIVATE_PRELIMINARY_NOT_FAMILY_ACCEPTANCE'),'automatic_successor_task_ids',succs,'family_accepted',false,'external_file_exported',false);
END;$f$;

CREATE FUNCTION population_top3000_202608_202609_v1.practical_delivery_record_export_v1(p_release text,p_receipts jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $f$
DECLARE r population_top3000_202608_202609_v1.practical_delivery_release_v1%rowtype;x jsonb;ds text;n bigint;want bigint;v jsonb;existing jsonb;cnt bigint;
BEGIN PERFORM population_top3000_202608_202609_v1.practical_delivery_guard_v1(p_release);SELECT * INTO STRICT r FROM population_top3000_202608_202609_v1.practical_delivery_release_v1 WHERE release_id=p_release;
IF jsonb_typeof(p_receipts) IS DISTINCT FROM 'array' OR jsonb_array_length(p_receipts)NOT BETWEEN 1 AND 4 THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_ACTUAL_EXPORT_RECEIPTS';END IF;
FOR x IN SELECT value FROM jsonb_array_elements(p_receipts) LOOP ds:=x->>'dataset';n:=(x->>'row_count')::bigint;want:=(r.manifest#>>ARRAY['expected_export_rows',ds])::bigint;
IF want IS NULL OR n IS DISTINCT FROM want OR ((x->>'file_sha256')~'^[0-9a-f]{64}$') IS DISTINCT FROM true OR coalesce((x->>'file_bytes')::bigint,0)<=0 OR x->>'actual_client_file_verified' IS DISTINCT FROM 'true' OR x->>'source_projection' IS DISTINCT FROM (CASE ds WHEN 'companies' THEN 'working_accepted_companies_v1' WHEN 'daily_features' THEN 'working_daily_features_v1' WHEN 'breadth' THEN 'working_breadth_preliminary_v1' WHEN 'readiness' THEN 'working_family_readiness_v1' ELSE '' END) OR x->>'source_projection_sha256' IS DISTINCT FROM r.manifest#>>ARRAY['view_hashes','population_top3000_202608_202609_v1.'||(x->>'source_projection')] OR x->>'qualification' IS DISTINCT FROM 'PRIVATE_PRELIMINARY_WORKING_NOT_FAMILY_ACCEPTANCE' OR x->>'dataset_values_sha256' IS DISTINCT FROM r.manifest#>>ARRAY['dataset_value_manifests',ds,'rows_sha256'] OR (population_top3000_202608_202609_v1.practical_delivery_digest_v1(ds,'*')->>'rows_sha256') IS DISTINCT FROM r.manifest#>>ARRAY['dataset_value_manifests',ds,'rows_sha256'] THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_EXPORT_BINDING';END IF;
SELECT receipt INTO existing FROM population_top3000_202608_202609_v1.practical_delivery_saved_export_v1 WHERE release_id=p_release AND dataset=ds;IF existing IS NOT NULL AND existing IS DISTINCT FROM x THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_SAVED_FILE_REPLAY_CONFLICT';END IF;
INSERT INTO population_top3000_202608_202609_v1.practical_delivery_saved_export_v1 VALUES(p_release,ds,x,encode(sha256(convert_to(x::text,'UTF8')),'hex')) ON CONFLICT DO NOTHING;END LOOP;
SELECT count(*) INTO cnt FROM population_top3000_202608_202609_v1.practical_delivery_saved_export_v1 WHERE release_id=p_release;
IF cnt=4 THEN UPDATE population_top3000_202608_202609_v1.pipeline_delivery SET artifact_state='EXPORTED_VERIFIED',artifact_receipts=(SELECT jsonb_agg(receipt ORDER BY dataset) FROM population_top3000_202608_202609_v1.practical_delivery_saved_export_v1 WHERE release_id=p_release) WHERE delivery_id=r.delivery_id;END IF;
RETURN jsonb_build_object('release_id',p_release,'saved_actual_dataset_files',cnt,'artifact_state',CASE WHEN cnt=4 THEN 'EXPORTED_VERIFIED' ELSE 'PENDING_EXPORT' END,'verification_scope','ACTUAL_WORKING_CLIENT_FILES_NOT_SOURCE_ACCURACY_OR_FAMILY_ACCEPTANCE','final_delivery',false,'final_release_pointer_changed',false);END;$f$;

REVOKE ALL ON FUNCTION population_top3000_202608_202609_v1.practical_delivery_guard_v1(text),population_top3000_202608_202609_v1.practical_delivery_gate_v1(),population_top3000_202608_202609_v1.practical_delivery_rows_v1(text,text),population_top3000_202608_202609_v1.practical_delivery_read_v1(text,text,text,integer,integer,boolean),population_top3000_202608_202609_v1.practical_delivery_digest_v1(text,text),population_top3000_202608_202609_v1.practical_delivery_bootstrap_v1(bigint),population_top3000_202608_202609_v1.practical_delivery_worker_v1(uuid,text),population_top3000_202608_202609_v1.practical_delivery_record_export_v1(text,jsonb) FROM PUBLIC,anon,authenticated,service_role;
DO $register$ BEGIN IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_adapter WHERE family_id='REF03' AND stage='DELIVER') THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_ADAPTER_PREIMAGE_NOT_ABSENT';END IF;
INSERT INTO population_top3000_202608_202609_v1.pipeline_adapter(family_id,stage,function_oid,function_sha256,resource_class,provider,enabled,reviewed_test_evidence,producer_revision,expected_batch_seconds) VALUES('REF03','DELIVER','population_top3000_202608_202609_v1.practical_delivery_worker_v1(uuid,text)'::regprocedure,encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.practical_delivery_worker_v1(uuid,text)'::regprocedure),'UTF8')),'hex'),'DATABASE',NULL,true,jsonb_build_object('assignment_event_id',74907,'private_working_only',true,'source_calls',0),'practical-delivery-v1',20);END;$register$;
